"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[3005],{61496:e=>{e.exports=JSON.parse('{"functions":[{"name":"Create","desc":"Create a TweenObject without playing it. Returns a TweenObject with\\n`:Play`, `:Pause`, `:Resume`, `:Cancel`, `:Reverse`, `:Scrub`, and\\n`:Destroy` methods.","params":[{"name":"target","desc":"the instance whose properties will be animated","lua_type":"Instance"},{"name":"goals","desc":"map of property names to their end values","lua_type":"{[string]: any}"},{"name":"config","desc":"animation options","lua_type":"{Duration: number?, Model: (string | (number) -> number)?, TimeWarp: ((number) -> number)?, CurveFn: ((number) -> any)?, ConstantSpeed: boolean?, ArcSamples: number?, UseSlerp: boolean?, UsePhysics: boolean?, From: {[string]: any}?}?"}],"returns":[{"desc":"a stopped TweenObject ready for manual lifecycle control","lua_type":"TweenObject"}],"function_type":"static","source":{"line":1233,"path":"src/ReplicatedStorage/SharedModules/MotionMaster.luau"}},{"name":"Play","desc":"Create and immediately play a TweenObject. Equivalent to calling\\n`MotionMaster.Create` followed by `:Play()`. Returns the TweenObject so\\nyou can attach callbacks or cancel playback later.\\n\\n```lua\\nMotionMaster.Play(frame, { Position = UDim2.fromScale(0.5, 0.5) }, { Duration = 0.4, Model = \\"EaseOutQuad\\" })\\n```","params":[{"name":"target","desc":"the instance whose properties will be animated","lua_type":"Instance"},{"name":"goals","desc":"map of property names to their end values","lua_type":"{[string]: any}"},{"name":"config","desc":"animation options","lua_type":"{Duration: number?, Model: (string | (number) -> number)?, TimeWarp: ((number) -> number)?, CurveFn: ((number) -> any)?, ConstantSpeed: boolean?, ArcSamples: number?, UseSlerp: boolean?, UsePhysics: boolean?, From: {[string]: any}?}?"}],"returns":[{"desc":"the playing TweenObject","lua_type":"TweenObject"}],"function_type":"static","source":{"line":1275,"path":"src/ReplicatedStorage/SharedModules/MotionMaster.luau"}},{"name":"Spring","desc":"Create and start a SpringDriver that continuously animates a single\\n`number` or `Vector3` property using exact ODE spring integration.\\nReturns a SpringDriver with `:SetTarget`, `:Impulse`, `:IsSettled`,\\n`:Stop`, and `:Destroy` methods.","params":[{"name":"target","desc":"the instance owning the property","lua_type":"Instance"},{"name":"prop","desc":"the property name to drive (must be `number` or `Vector3`)","lua_type":"string"},{"name":"config","desc":"spring parameters","lua_type":"{Omega: number?, Zeta: number?, MaxSubsteps: number?, FixedDt: number?}?"}],"returns":[{"desc":"the running SpringDriver, or `nil` if the property could not be read","lua_type":"SpringDriver"}],"function_type":"static","source":{"line":1294,"path":"src/ReplicatedStorage/SharedModules/MotionMaster.luau"}},{"name":"Sequence","desc":"Create a new Sequence that chains or parallelizes TweenObjects.\\nCall `:Add(tweenObj, delay?)` to enqueue tweens, then `:Play()` to run\\nthem. Attach `:OnComplete(cb)` for a callback after all tweens finish.","params":[{"name":"config","desc":"pass `Parallel = true` to play all tweens simultaneously","lua_type":"{Parallel: boolean?}?"}],"returns":[{"desc":"a new Sequence object","lua_type":"Sequence"}],"function_type":"static","source":{"line":1317,"path":"src/ReplicatedStorage/SharedModules/MotionMaster.luau"}},{"name":"fromPreset","desc":"Instantiate and start a SpringDriver using a named preset configuration\\nfrom `MotionMaster.Presets` (e.g. `\\"UIPanel\\"`, `\\"CameraFollow\\"`,\\n`\\"DoorBouncy\\"`). Errors if the preset name is unknown.","params":[{"name":"presetName","desc":"key into `MotionMaster.Presets`","lua_type":"string"},{"name":"target","desc":"the instance owning the property","lua_type":"Instance"},{"name":"prop","desc":"the property name to drive","lua_type":"string"}],"returns":[{"desc":"the running SpringDriver","lua_type":"SpringDriver"}],"function_type":"static","source":{"line":1334,"path":"src/ReplicatedStorage/SharedModules/MotionMaster.luau"}},{"name":"SplineMove","desc":"Animate a `BasePart` along an arc-length-reparameterized Catmull-Rom\\nspline defined by `controlPoints`. Each control point may be a\\n`BasePart` (position is extracted) or a `Vector3`. Requires at least\\n2 control points. `ConstantSpeed` defaults to `true`.\\n\\nReturns a TweenObject; call `:Play()` to start movement.","params":[{"name":"target","desc":"the part whose `Position` will be driven","lua_type":"BasePart"},{"name":"controlPoints","desc":"ordered list of control points (minimum 2)","lua_type":"{BasePart | Vector3}"},{"name":"config","desc":"animation options","lua_type":"{Duration: number?, Model: (string | (number) -> number)?, ConstantSpeed: boolean?, ArcSamples: number?, TimeWarp: ((number) -> number)?}?"}],"returns":[{"desc":"a stopped TweenObject ready for playback","lua_type":"TweenObject"}],"function_type":"static","source":{"line":1357,"path":"src/ReplicatedStorage/SharedModules/MotionMaster.luau"}},{"name":"PivotMove","desc":"Animate a `Model` to a target `CFrame` using `:PivotTo()`, which\\npreserves the relative offsets of all parts inside the model.\\nInternally creates a proxy that routes `CFrame` writes through\\n`:PivotTo()` so all standard `MotionMaster.Create` config fields apply.\\n\\nReturns a TweenObject; call `:Play()` to start the animation.","params":[{"name":"model","desc":"the model to animate","lua_type":"Model"},{"name":"targetCFrame","desc":"the destination pivot CFrame","lua_type":"CFrame"},{"name":"config","desc":"animation options","lua_type":"{Duration: number?, Model: (string | (number) -> number)?, TimeWarp: (string | (number) -> number)?, UseSlerp: boolean?, UsePhysics: boolean?}?"}],"returns":[{"desc":"a stopped TweenObject ready for playback","lua_type":"TweenObject"}],"function_type":"static","source":{"line":1454,"path":"src/ReplicatedStorage/SharedModules/MotionMaster.luau"}}],"properties":[],"types":[],"name":"MotionMaster","desc":"The project\'s animation library. Use instead of TweenService for all\\nclient-side animations. Supports 15+ motion models (classic easing,\\nB\xe9zier, spline, spring ODE, kinematics), arc-length reparameterization,\\ntime-warp, and CFrame quaternion SLERP.\\n\\n`MotionMaster.Create` returns a **TweenObject** with full lifecycle\\ncontrol: `:Play`, `:Pause`, `:Resume`, `:Cancel`, `:Reverse`, `:Scrub`,\\n`:Destroy`.\\n\\n`MotionMaster.Spring` returns a **SpringDriver** \u2014 a live, frame-rate-\\nindependent spring that follows a moving target with exact ODE integration.","source":{"line":47,"path":"src/ReplicatedStorage/SharedModules/MotionMaster.luau"}}')}}]);